pragma solidity >=0.8.0;
contract GasProbe {
    uint256 public entryGas;
    uint256 public exitGas;
    uint256 public lastN;
    event GasRecorded(uint256 entryG, uint256 exitG, uint256 n);
    function getGas() public view returns (uint256) {
        return gasleft();
    }
    function recordEntry(uint256 n) public {
        lastN = n;
        entryGas = gasleft();
        uint256 s = 0;
        for (uint256 i = 0; i < n; i++) {
            s += i * 3;
        }
        exitGas = gasleft();
        emit GasRecorded(entryGas, exitGas, n);
    }
}
